Here is the commit message:
IB/core: Use GRH when the path hop-limit > 0

According to IBTA spec v1.3 section 12.7.19, QPs should use GRH when
the path returned by the SA has hop-limit > 0. Currently, we do that
only for the > 1 case, fix that.

Fixes: 6d969a471ba1 ('IB/sa: Add ib_init_ah_from_path()')
Signed-off-by: Or Gerlitz <ogerlitz@mellanox.com>
Reviewed-by: Jason Gunthorpe <jgunthorpe@obsidianresearch.com>
Signed-off-by: Doug Ledford <dledford@redhat.com>

Here is the root cause:
The bug was caused by the conditional check in the `ib_init_ah_from_path` function, which incorrectly required the hop limit to be greater than 1 to use the Generic Route Header (GRH). This did not comply with the IBTA specification, which states that GRH should be used when the hop limit is greater than 0. As a result, valid paths with a hop limit of 1 were not utilizing GRH, leading to potential connectivity issues.

Here is the patch:

 int ib_init_ah_from_path(struct ib_device *device, u8 port_num,
 			 struct ib_sa_path_rec *rec, struct ib_ah_attr *ah_attr)
 {
 	int ret;
 	u16 gid_index;
 	int use_roce;
 	struct net_device *ndev = NULL;

 	memset(ah_attr, 0, sizeof *ah_attr);
 	ah_attr->dlid = be16_to_cpu(rec->dlid);
 	ah_attr->sl = rec->sl;
 	ah_attr->src_path_bits = be16_to_cpu(rec->slid) &
 				 get_src_path_mask(device, port_num);
 	ah_attr->port_num = port_num;
 	ah_attr->static_rate = rec->rate;

 	use_roce = rdma_cap_eth_ah(device, port_num);

 	if (use_roce) {
 		struct net_device *idev;
 		struct net_device *resolved_dev;
 		struct rdma_dev_addr dev_addr = {.bound_dev_if = rec->ifindex,
 						 .net = rec->net ? rec->net :
 							 &init_net};
 		union {
 			struct sockaddr     _sockaddr;
 			struct sockaddr_in  _sockaddr_in;
 			struct sockaddr_in6 _sockaddr_in6;
 		} sgid_addr, dgid_addr;

 		if (!device->get_netdev)
 			return -EOPNOTSUPP;

 		rdma_gid2ip(&sgid_addr._sockaddr, &rec->sgid);
 		rdma_gid2ip(&dgid_addr._sockaddr, &rec->dgid);

 		/* validate the route */
 		ret = rdma_resolve_ip_route(&sgid_addr._sockaddr,
 					    &dgid_addr._sockaddr, &dev_addr);
 		if (ret)
 			return ret;

 		if ((dev_addr.network == RDMA_NETWORK_IPV4 ||
 		     dev_addr.network == RDMA_NETWORK_IPV6) &&
 		    rec->gid_type != IB_GID_TYPE_ROCE_UDP_ENCAP)
 			return -EINVAL;

 		idev = device->get_netdev(device, port_num);
 		if (!idev)
 			return -ENODEV;

 		resolved_dev = dev_get_by_index(dev_addr.net,
 						dev_addr.bound_dev_if);
 		if (resolved_dev->flags & IFF_LOOPBACK) {
 			dev_put(resolved_dev);
 			resolved_dev = idev;
 			dev_hold(resolved_dev);
 		}
 		ndev = ib_get_ndev_from_path(rec);
 		rcu_read_lock();
 		if ((ndev && ndev != resolved_dev) ||
 		    (resolved_dev != idev &&
 		     !rdma_is_upper_dev_rcu(idev, resolved_dev)))
 			ret = -EHOSTUNREACH;
 		rcu_read_unlock();
 		dev_put(idev);
 		dev_put(resolved_dev);
 		if (ret) {
 			if (ndev)
 				dev_put(ndev);
 			return ret;
 		}
 	}

-	if (rec->hop_limit > 1 || use_roce) {
+	if (rec->hop_limit > 0 || use_roce) {
 		ah_attr->ah_flags = IB_AH_GRH;
 		ah_attr->grh.dgid = rec->dgid;

 		ret = ib_find_cached_gid_by_port(device, &rec->sgid,
 						 rec->gid_type, port_num, ndev,
 						 &gid_index);
 		if (ret) {
 			if (ndev)
 				dev_put(ndev);
 			return ret;
 		}

 		ah_attr->grh.sgid_index    = gid_index;
 		ah_attr->grh.flow_label    = be32_to_cpu(rec->flow_label);
 		ah_attr->grh.hop_limit     = rec->hop_limit;
 		ah_attr->grh.traffic_class = rec->traffic_class;
 		if (ndev)
 			dev_put(ndev);
 	}

 	if (use_roce)
 		memcpy(ah_attr->dmac, rec->dmac, ETH_ALEN);

 	return 0;
 }
 EXPORT_SYMBOL(ib_init_ah_from_path);


